export const envelope = [15, 28, 21];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;

  // 1. Theme Palette
  const planks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const log = api.theme?.wood?.log || "minecraft:oak_log";
  const stripped = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const stairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const slab = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const fence = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const trapdoor = api.theme?.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const darkPlanks = "minecraft:dark_oak_planks";
  const darkLog = "minecraft:dark_oak_log";
  const darkStairs = "minecraft:dark_oak_stairs";
  const darkSlab = "minecraft:dark_oak_slab";
  const chain = "minecraft:chain[axis=y]";

  function clean(blockStr) {
    return blockStr.split("[")[0];
  }

  function getLog(base, axis = "y") {
    return `${clean(base)}[axis=${axis}]`;
  }

  function getStairs(base, facing = "north", half = "bottom", shape = "straight") {
    return `${clean(base)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function getSlab(base, type = "bottom") {
    return `${clean(base)}[type=${type}]`;
  }

  function getTrapdoor(base, facing = "north", half = "bottom", open = false) {
    return `${clean(base)}[facing=${facing},half=${half},open=${open}]`;
  }

  function getLadder(facing = "north") {
    return `minecraft:ladder[facing=${facing}]`;
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  const seatY = 4;

  // 2. Ground Conformity & Pilings (Rule 6)
  const footprint = [];
  // Wheels footprint
  for (const x of [2, 3, 11, 12]) {
    for (let z = 5; z <= 7; z++) footprint.push([x, z]);
    for (let z = 13; z <= 15; z++) footprint.push([x, z]);
  }
  // Chassis skids footprint
  for (const x of [3, 4, 6, 7, 8, 10, 11]) {
    footprint.push([x, 3], [x, 4], [x, 16], [x, 17]);
  }

  for (const [fx, fz] of footprint) {
    const gh = Math.round(api.heightAt(fx, fz));
    const targetY = Math.max(0, Math.min(seatY, seatY + gh));
    if (targetY < seatY) {
      for (let y = seatY - 1; y >= targetY; y--) {
        set(fx, y, fz, getLog(log, "y"));
      }
    } else if (targetY > seatY) {
      for (let y = seatY; y <= Math.min(seatY + 3, seatY + gh); y++) {
        set(fx, y, fz, getLog(log, "y"));
      }
    }
  }

  // 3. Heavy Wheeled Base & Sled Platform (Y = 4 to 8)
  // Axles
  for (let x = 2; x <= 12; x++) {
    set(x, 5, 6, getLog(log, "x"));
    set(x, 5, 14, getLog(log, "x"));
  }

  // Wheels function
  function placeWheel(xCenter, zCenter) {
    for (const x of [xCenter, xCenter === 2 ? 3 : 11]) {
      // Hub
      set(x, 5, zCenter, stripped);
      // Cardinal rim blocks
      set(x, 6, zCenter, darkPlanks);
      set(x, 4, zCenter, darkPlanks);
      set(x, 5, zCenter - 1, stripped);
      set(x, 5, zCenter + 1, stripped);
      // Rounded corners
      set(x, 6, zCenter - 1, getStairs(darkStairs, "south", "top"));
      set(x, 6, zCenter + 1, getStairs(darkStairs, "north", "top"));
      set(x, 4, zCenter - 1, getStairs(darkStairs, "south", "bottom"));
      set(x, 4, zCenter + 1, getStairs(darkStairs, "north", "bottom"));
    }
  }

  placeWheel(2, 6);
  placeWheel(12, 6);
  placeWheel(2, 14);
  placeWheel(12, 14);

  // Longitudinal chassis beams (Y = 6)
  for (let z = 3; z <= 17; z++) {
    set(3, 6, z, getLog(log, "z"));
    set(4, 6, z, planks);
    set(6, 6, z, getLog(log, "z"));
    set(7, 6, z, getLog(log, "z"));
    set(8, 6, z, getLog(log, "z"));
    set(10, 6, z, planks);
    set(11, 6, z, getLog(log, "z"));
  }

  // Cross chassis ties (Y = 6)
  for (const z of [3, 6, 9, 12, 14, 17]) {
    for (let x = 3; x <= 11; x++) {
      set(x, 6, z, getLog(log, "x"));
    }
  }

  // Platform deck (Y = 7)
  for (let x = 3; x <= 11; x++) {
    for (let z = 3; z <= 17; z++) {
      set(x, 7, z, planks);
    }
  }
  // Timber rim around platform
  for (let z = 3; z <= 17; z++) {
    set(3, 7, z, getLog(log, "z"));
    set(11, 7, z, getLog(log, "z"));
  }
  for (let x = 3; x <= 11; x++) {
    set(x, 7, 3, getLog(log, "x"));
    set(x, 7, 17, getLog(log, "x"));
  }

  // Towing cleats & platform posts (Y = 8)
  for (const [px, pz] of [[3, 3], [11, 3], [3, 17], [11, 17], [5, 3], [7, 3], [9, 3]]) {
    set(px, 8, pz, fence);
  }
  set(7, 7, 2, fence);
  set(7, 7, 1, chain);

  // 4. Horse Legs (Y = 8 to 14)
  // Front-Left (X=4..5, Z=5..6) & Front-Right (X=9..10, Z=5..6)
  for (let y = 8; y <= 14; y++) {
    // Left
    set(4, y, 5, getLog(log, "y"));
    set(5, y, 5, planks);
    set(4, y, 6, planks);
    set(5, y, 6, getLog(log, "y"));
    // Right
    set(9, y, 5, planks);
    set(10, y, 5, getLog(log, "y"));
    set(9, y, 6, getLog(log, "y"));
    set(10, y, 6, planks);
  }

  // Front Hoof flares
  set(4, 8, 4, getStairs(stairs, "south", "bottom"));
  set(5, 8, 4, getStairs(stairs, "south", "bottom"));
  set(9, 8, 4, getStairs(stairs, "south", "bottom"));
  set(10, 8, 4, getStairs(stairs, "south", "bottom"));
  set(3, 8, 5, getStairs(stairs, "east", "bottom"));
  set(3, 8, 6, getStairs(stairs, "east", "bottom"));
  set(11, 8, 5, getStairs(stairs, "west", "bottom"));
  set(11, 8, 6, getStairs(stairs, "west", "bottom"));

  // Hind Legs with anatomically angled hocks (Y = 8 to 14)
  for (let y = 8; y <= 10; y++) {
    set(4, y, 13, getLog(log, "y"));
    set(5, y, 13, planks);
    set(4, y, 14, planks);
    set(5, y, 14, getLog(log, "y"));

    set(9, y, 13, planks);
    set(10, y, 13, getLog(log, "y"));
    set(9, y, 14, getLog(log, "y"));
    set(10, y, 14, planks);
  }
  // Hock joint (Y = 11..12) - shifted back
  for (let y = 11; y <= 12; y++) {
    set(4, y, 14, getLog(log, "y"));
    set(5, y, 14, planks);
    set(4, y, 15, planks);
    set(5, y, 15, getLog(log, "y"));

    set(9, y, 14, planks);
    set(10, y, 14, getLog(log, "y"));
    set(9, y, 15, getLog(log, "y"));
    set(10, y, 15, planks);
  }
  // Upper thighs (Y = 13..14)
  for (let y = 13; y <= 14; y++) {
    for (let z = 13; z <= 15; z++) {
      set(4, y, z, getLog(log, "y"));
      set(5, y, z, planks);
      set(9, y, z, planks);
      set(10, y, z, getLog(log, "y"));
    }
  }

  // Hind Hoof flares
  set(4, 8, 15, getStairs(stairs, "north", "bottom"));
  set(5, 8, 15, getStairs(stairs, "north", "bottom"));
  set(9, 8, 15, getStairs(stairs, "north", "bottom"));
  set(10, 8, 15, getStairs(stairs, "north", "bottom"));

  // Cross-braces between legs
  for (let x = 6; x <= 8; x++) {
    set(x, 9, 5, getLog(log, "x"));
    set(x, 12, 6, getLog(log, "x"));
    set(x, 9, 13, getLog(log, "x"));
    set(x, 12, 14, getLog(log, "x"));
  }

  // Stealth Access Ladder up the inner right hind leg
  for (let y = 8; y <= 13; y++) {
    set(8, y, 13, getLadder("east"));
  }

  // 5. Torso / Hull Construction (Y = 14 to 20, Z = 4 to 17)
  // Belly floor (Y = 14)
  for (let x = 4; x <= 10; x++) {
    for (let z = 5; z <= 16; z++) {
      set(x, 14, z, planks);
    }
  }
  // Secret belly trapdoor seam
  set(7, 14, 12, getTrapdoor(trapdoor, "north", "bottom", false));
  set(8, 14, 12, getTrapdoor(trapdoor, "north", "bottom", false));

  // Torso outer shell fill
  for (let y = 14; y <= 20; y++) {
    for (let z = 4; z <= 17; z++) {
      let xMin = 4, xMax = 10;

      if (y === 14) {
        if (z < 5 || z > 16) continue;
        xMin = 4; xMax = 10;
      } else if (y === 15 || y === 16 || y === 17) {
        if (z >= 6 && z <= 14) {
          xMin = 3; xMax = 11;
        } else if (z === 17) {
          xMin = 5; xMax = 9;
        } else {
          xMin = 4; xMax = 10;
        }
      } else if (y === 18) {
        if (z > 16) continue;
        if (z >= 5 && z <= 14) {
          xMin = 4; xMax = 10;
        } else {
          xMin = 5; xMax = 9;
        }
      } else if (y === 19) {
        if (z < 4 || z > 15) continue;
        if (z >= 5 && z <= 14) {
          xMin = 5; xMax = 9;
        } else {
          xMin = 6; xMax = 8;
        }
      } else if (y === 20) {
        if (z < 4 || z > 14) continue;
        xMin = 6; xMax = 8;
      }

      for (let x = xMin; x <= xMax; x++) {
        const isRib = (z % 3 === 0) || (x === xMin || x === xMax);
        const block = isRib ? stripped : planks;
        set(x, y, z, block);
      }
    }
  }

  // Hull rub-rails & flank bevels
  for (let z = 6; z <= 14; z++) {
    set(3, 16, z, getLog(log, "z"));
    set(11, 16, z, getLog(log, "z"));
    set(3, 18, z, getStairs(stairs, "east", "top"));
    set(11, 18, z, getStairs(stairs, "west", "top"));
    set(3, 14, z, getStairs(stairs, "west", "bottom"));
    set(11, 14, z, getStairs(stairs, "east", "bottom"));
  }

  // Chest medallion boss & rigging chains
  set(7, 17, 3, getTrapdoor(trapdoor, "north", "bottom", false));
  for (let y = 10; y <= 13; y++) {
    set(4, y, 4, chain);
    set(10, y, 4, chain);
  }

  // 6. Carve the Hollow Soldier Interior (Rule for interiors)
  // min: [5, 15, 8], max: [9, 18, 13]
  for (let x = 5; x <= 9; x++) {
    for (let y = 15; y <= 18; y++) {
      for (let z = 8; z <= 13; z++) {
        set(x, y, z, "minecraft:air");
      }
    }
  }

  // Scout peepholes on flanks
  set(3, 16, 10, getTrapdoor(trapdoor, "west", "bottom", true));
  set(11, 16, 10, getTrapdoor(trapdoor, "east", "bottom", true));

  // 7. Neck and Mane (Y = 18 to 25)
  const neckProfile = [
    { y: 18, zMin: 3, zMax: 5, xMin: 5, xMax: 9 },
    { y: 19, zMin: 2, zMax: 5, xMin: 5, xMax: 9 },
    { y: 20, zMin: 2, zMax: 4, xMin: 5, xMax: 9 },
    { y: 21, zMin: 1, zMax: 4, xMin: 5, xMax: 9 },
    { y: 22, zMin: 1, zMax: 3, xMin: 5, xMax: 9 },
    { y: 23, zMin: 1, zMax: 3, xMin: 5, xMax: 9 },
    { y: 24, zMin: 1, zMax: 3, xMin: 6, xMax: 8 }
  ];

  for (const n of neckProfile) {
    for (let x = n.xMin; x <= n.xMax; x++) {
      for (let z = n.zMin; z <= n.zMax; z++) {
        set(x, n.y, z, planks);
      }
    }
    // Front throat curve
    for (let x = n.xMin; x <= n.xMax; x++) {
      set(x, n.y, n.zMin, getStairs(stairs, "north", "top"));
    }
  }

  // Mane (Stepped dorsal crest)
  set(7, 20, 5, darkPlanks);
  set(7, 21, 5, getLog(darkLog, "z"));
  set(7, 21, 4, darkPlanks);
  set(7, 22, 4, getLog(darkLog, "z"));
  set(7, 22, 5, getStairs(darkStairs, "south", "bottom"));
  set(7, 23, 4, darkPlanks);
  set(6, 23, 4, getSlab(darkSlab, "bottom"));
  set(8, 23, 4, getSlab(darkSlab, "bottom"));
  set(7, 24, 4, getStairs(darkStairs, "north", "bottom"));
  set(7, 25, 3, getSlab(darkSlab, "bottom"));

  // 8. Head, Muzzle, Ears, Eyes (Y = 22 to 27, Z = 0 to 4)
  // Jowl and Cheeks (Y = 23..24)
  for (let y = 23; y <= 24; y++) {
    for (let x = 5; x <= 9; x++) {
      set(x, y, 2, planks);
      set(x, y, 3, planks);
    }
    set(4, y, 2, getStairs(stairs, "east", "bottom"));
    set(10, y, 2, getStairs(stairs, "west", "bottom"));
  }

  // Muzzle (pointing NORTH to -Z)
  // Lower jaw (Y = 23)
  for (let x = 6; x <= 8; x++) {
    set(x, 23, 1, planks);
    set(x, 23, 0, getStairs(stairs, "south", "top"));
  }
  // Upper snout & nostrils (Y = 24)
  for (let x = 6; x <= 8; x++) {
    set(x, 24, 1, getLog(log, "z"));
  }
  set(7, 24, 0, getLog(log, "z"));
  set(6, 24, 0, getStairs(stairs, "north", "bottom"));
  set(8, 24, 0, getStairs(stairs, "north", "bottom"));

  // Forehead & Brow (Y = 25)
  for (let x = 5; x <= 9; x++) {
    for (let z = 1; z <= 3; z++) {
      set(x, 25, z, planks);
    }
  }
  for (let x = 6; x <= 8; x++) {
    set(x, 25, 1, getStairs(stairs, "north", "bottom"));
  }
  // Eyes
  set(4, 25, 2, getTrapdoor(trapdoor, "west", "bottom", false));
  set(10, 25, 2, getTrapdoor(trapdoor, "east", "bottom", false));

  // Head Crown (Y = 26)
  for (let x = 6; x <= 8; x++) {
    set(x, 26, 2, planks);
    set(x, 26, 3, getSlab(slab, "bottom"));
  }

  // Ears (Y = 26..27)
  set(5, 26, 2, getLog(stripped, "y"));
  set(9, 26, 2, getLog(stripped, "y"));
  set(5, 27, 2, getStairs(darkStairs, "north", "bottom"));
  set(9, 27, 2, getStairs(darkStairs, "north", "bottom"));

  // 9. Flowing Carved Tail (Y = 9 to 17, Z = 17 to 19)
  set(7, 17, 17, getLog(log, "z"));

  set(7, 16, 18, getLog(log, "y"));
  set(6, 16, 18, getStairs(stairs, "north", "top"));
  set(8, 16, 18, getStairs(stairs, "north", "top"));

  set(7, 15, 18, getLog(log, "y"));
  set(6, 15, 18, planks);
  set(8, 15, 18, planks);

  set(7, 14, 18, getLog(log, "y"));
  set(7, 14, 19, getStairs(stairs, "north", "bottom"));

  set(7, 13, 19, getLog(log, "y"));
  set(6, 13, 19, fence);
  set(8, 13, 19, fence);

  set(7, 12, 19, getLog(log, "y"));

  set(7, 11, 19, getStairs(stairs, "south", "bottom"));
  set(7, 11, 18, getLog(log, "y"));

  set(7, 10, 18, getLog(log, "y"));
  set(7, 9, 18, getStairs(stairs, "south", "bottom"));

  // 10. Return Result
  return {
    name: "Trojan Horse",
    seatY: seatY,
    anchors: {
      front: [7, 24, 0],
      door: [7, 7, 11]
    },
    interiors: [
      {
        min: [5, 15, 8],
        max: [9, 18, 13],
        kind: "vault"
      }
    ]
  };
}

abandoned_siege_engine.source:
export const envelope = [11, 10, 13];

export default function build(api) {
  const [W, H, D] = api.size;
  const rand = api.random;

  // Retrieve town carpentry and masonry palette from theme
  const tWood = api.theme?.wood || {};
  const tStone = api.theme?.stone || {};

  const woodLog = tWood.log || "minecraft:oak_log";
  const woodPlanks = tWood.planks || "minecraft:oak_planks";
  const woodStripped = tWood.stripped || "minecraft:stripped_oak_log";
  const woodStairs = tWood.stairs || "minecraft:oak_stairs";
  const woodSlab = tWood.slab || "minecraft:oak_slab";
  const woodFence = tWood.fence || "minecraft:oak_fence";
  const woodTrapdoor = tWood.trapdoor || "minecraft:oak_trapdoor";

  // Dried ox-hides, cured leather, and siege ironwork
  const hidePrimary = "minecraft:terracotta";
  const hideSecondary = "minecraft:brown_wool";
  const hideTertiary = "minecraft:brown_terracotta";
  const hideRough = "minecraft:packed_mud";
  const ironHead = "minecraft:iron_block";
  const ironAnvil = "minecraft:anvil";
  const chainBlock = "minecraft:chain";
  const ironBar = "minecraft:iron_bars";

  // Base names for state formatting
  function clean(b) {
    return b ? b.split("[")[0] : "minecraft:oak_planks";
  }

  const logBase = clean(woodLog);
  const strippedBase = clean(woodStripped);
  const stairsBase = clean(woodStairs);
  const slabBase = clean(woodSlab);

  function logX() { return `${logBase}[axis=x]`; }
  function logY() { return `${logBase}[axis=y]`; }
  function logZ() { return `${logBase}[axis=z]`; }
  function strLogX() { return `${strippedBase}[axis=x]`; }
  function strLogY() { return `${strippedBase}[axis=y]`; }
  function strLogZ() { return `${strippedBase}[axis=z]`; }
  function stairN(half = "bottom") { return `${stairsBase}[facing=north,half=${half}]`; }
  function stairS(half = "bottom") { return `${stairsBase}[facing=south,half=${half}]`; }
  function stairE(half = "bottom") { return `${stairsBase}[facing=east,half=${half}]`; }
  function stairW(half = "bottom") { return `${stairsBase}[facing=west,half=${half}]`; }
  function slabBottom() { return `${slabBase}[type=bottom]`; }
  function slabTop() { return `${slabBase}[type=top]`; }

  function set(x, y, z, b) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, b);
    }
  }

  // Terrain height conformity: extends footings down to real ground
  function groundSole(x, yBase, z, b) {
    const gh = Math.round(api.heightAt(x, z));
    const low = Math.min(yBase, gh);
    const high = Math.max(yBase, gh);
    for (let y = low; y <= high; y++) {
      set(x, y, z, b);
    }
  }

  function placeBeamX(x1, x2, y, z, block) {
    const min = Math.min(x1, x2);
    const max = Math.max(x1, x2);
    for (let x = min; x <= max; x++) {
      set(x, y, z, block);
    }
  }

  function placeBeamZ(x, y, z1, z2, block) {
    const min = Math.min(z1, z2);
    const max = Math.max(z1, z2);
    for (let z = min; z <= max; z++) {
      set(x, y, z, block);
    }
  }

  function pickHide(r) {
    if (r < 0.35) return hidePrimary;
    if (r < 0.65) return hideSecondary;
    if (r < 0.85) return hideTertiary;
    return hideRough;
  }

  // Sturdy multi-block solid timber wheel
  function buildWheel(wx, wz, broken = false) {
    if (broken) {
      groundSole(wx, 0, wz, woodPlanks);
      set(wx, 0, wz - 1, woodSlab);
      set(wx, 0, wz + 1, woodSlab);
      set(wx, 1, wz, woodPlanks);
      return;
    }
    for (let dz = -1; dz <= 1; dz++) {
      for (let dy = 0; dy <= 2; dy++) {
        const isCorner = (dz === -1 || dz === 1) && (dy === 0 || dy === 2);
        if (!isCorner) {
          set(wx, dy, wz + dz, logZ());
        } else {
          set(wx, dy, wz + dz, woodPlanks);
        }
        if (dy === 0) {
          groundSole(wx, 0, wz + dz, woodPlanks);
        }
      }
    }
    set(wx, 1, wz, woodStripped);
  }

  const variant = (api.instance ? api.instance.index : 0) % 4;
  let engineName = "Achaean Siege Engine";

  if (variant === 0) {
    // -------------------------------------------------------------------------
    // VARIANT 0: Heavy A-Frame Battering Ram with Ox-Hide Canopy
    // -------------------------------------------------------------------------
    engineName = "Achaean Heavy Battering Ram";

    // 4 Heavy spoked wheels
    buildWheel(1, 3);
    buildWheel(1, 9);
    buildWheel(9, 3);
    buildWheel(9, 9);

    // Axles
    placeBeamX(1, 9, 1, 3, logX());
    placeBeamX(1, 9, 1, 9, logX());

    // Carriage side sills
    placeBeamZ(2, 1, 1, 11, logZ());
    placeBeamZ(8, 1, 1, 11, logZ());

    // Crossbeams and footing anchors
    for (const z of [1, 3, 6, 9, 11]) {
      placeBeamX(2, 8, 1, z, logX());
      groundSole(2, 0, z, woodLog);
      groundSole(8, 0, z, woodLog);
    }

    // Timber floor deck
    for (let z = 2; z <= 10; z++) {
      for (let x = 3; x <= 7; x++) {
        set(x, 1, z, woodPlanks);
      }
    }

    // Side waist rails
    placeBeamZ(2, 2, 1, 11, woodPlanks);
    placeBeamZ(8, 2, 1, 11, woodPlanks);

    // Continuous 6-connected A-frame trestle uprights
    for (const z of [2, 6, 10]) {
      // West truss
      set(2, 2, z, logY());
      set(2, 3, z, logY());
      set(3, 3, z, woodPlanks);
      set(3, 4, z, logY());
      set(3, 5, z, logY());
      set(4, 5, z, woodPlanks);
      set(4, 6, z, logY());
      set(4, 7, z, logY());
      set(5, 7, z, woodPlanks);

      // East truss
      set(8, 2, z, logY());
      set(8, 3, z, logY());
      set(7, 3, z, woodPlanks);
      set(7, 4, z, logY());
      set(7, 5, z, logY());
      set(6, 5, z, woodPlanks);
      set(6, 6, z, logY());
      set(6, 7, z, logY());
    }

    // Ridge beam along peak
    placeBeamZ(5, 8, 1, 11, strLogZ());

    // Hide-draped protective pitched roof
    for (let z = 1; z <= 11; z++) {
      set(5, 9, z, slabBottom());

      set(4, 8, z, pickHide(rand()));
      set(6, 8, z, pickHide(rand()));
      set(4, 7, z, slabTop());
      set(6, 7, z, slabTop());

      set(3, 6, z, pickHide(rand()));
      set(7, 6, z, pickHide(rand()));
      set(3, 5, z, stairW());
      set(7, 5, z, stairE());

      set(2, 4, z, pickHide(rand()));
      set(8, 4, z, pickHide(rand()));
      set(1, 4, z, slabBottom());
      set(9, 4, z, slabBottom());
    }

    // Front and rear gables
    for (const z of [1, 11]) {
      set(3, 3, z, woodFence);
      set(7, 3, z, woodFence);
      set(4, 4, z, woodFence);
      set(6, 4, z, woodFence);
      set(4, 5, z, woodFence);
      set(6, 5, z, woodFence);
      set(5, 7, z, woodPlanks);
    }

    // Suspended Ram Beam with Cast Iron Ram-Head
    set(5, 3, 0, ironHead);
    set(5, 4, 0, ironAnvil);
    set(5, 3, 1, ironHead);
    set(5, 2, 0, stairN("top"));
    set(4, 3, 0, stairW("top"));
    set(6, 3, 0, stairE("top"));

    // Main pine log ram
    placeBeamZ(5, 3, 2, 10, strLogZ());

    // Rear push crossbars
    set(4, 3, 10, logX());
    set(6, 3, 10, logX());
    set(5, 3, 11, logZ());

    // Iron suspension chains hanging from roof ridge
    for (const z of [3, 6, 9]) {
      set(5, 7, z, chainBlock);
      set(5, 6, z, chainBlock);
      set(5, 5, z, chainBlock);
      set(5, 4, z, chainBlock);
    }

    // Wheel wedges and rear ladder
    set(1, 0, 1, stairS());
    set(1, 0, 5, stairN());
    set(9, 0, 1, stairS());
    set(9, 0, 5, stairN());
    groundSole(1, 0, 1, woodPlanks);
    groundSole(1, 0, 5, woodPlanks);
    groundSole(9, 0, 1, woodPlanks);
    groundSole(9, 0, 5, woodPlanks);

    for (let y = 1; y <= 5; y++) {
      set(8, y, 11, woodFence);
    }

  } else if (variant === 1) {
    // -------------------------------------------------------------------------
    // VARIANT 1: Wheeled Mantlet & Artillery Shielding Machine
    // -------------------------------------------------------------------------
    engineName = "Greek Assault Mantlet Screen";

    // 3 sound wheels, 1 broken front-west wheel
    buildWheel(1, 3, true);
    buildWheel(1, 9, false);
    buildWheel(9, 3, false);
    buildWheel(9, 9, false);

    // Axles
    placeBeamX(1, 9, 1, 3, logX());
    placeBeamX(1, 9, 1, 9, logX());

    // Chassis frame
    placeBeamZ(2, 1, 1, 11, logZ());
    placeBeamZ(8, 1, 1, 11, logZ());

    for (const z of [1, 3, 6, 9, 11]) {
      placeBeamX(2, 8, 1, z, logX());
      groundSole(2, 0, z, woodLog);
      groundSole(8, 0, z, woodLog);
    }

    // Lower deck
    for (let z = 2; z <= 10; z++) {
      for (let x = 3; x <= 7; x++) {
        set(x, 1, z, woodPlanks);
      }
    }

    // Sloped Mantlet Shield Facade (slanted from Z=1 at Y=1 back to Z=4 at Y=8)
    for (let x = 2; x <= 8; x++) {
      set(x, 1, 1, logX());
      groundSole(x, 0, 1, woodLog);
      set(x, 2, 1, pickHide(rand()));
    }
    for (let x = 2; x <= 8; x++) {
      set(x, 3, 2, pickHide(rand()));
      set(x, 2, 2, woodPlanks);
      if (x === 3 || x === 7) {
        set(x, 4, 2, woodFence); // Arrow slit
      } else {
        set(x, 4, 2, pickHide(rand()));
      }
    }
    for (let x = 2; x <= 8; x++) {
      set(x, 5, 3, pickHide(rand()));
      set(x, 4, 3, woodPlanks);
      if (x === 5) {
        set(x, 6, 3, woodFence); // View port
      } else {
        set(x, 6, 3, pickHide(rand()));
      }
    }
    for (let x = 2; x <= 8; x++) {
      set(x, 7, 4, pickHide(rand()));
      set(x, 6, 4, woodPlanks);
      set(x, 8, 4, stairS()); // Parapet coping
    }

    // Flying diagonal timber rear buttresses
    set(2, 6, 5, logZ());
    set(2, 5, 6, logZ());
    set(2, 4, 7, logZ());
    set(2, 3, 8, logZ());
    set(2, 2, 9, logZ());

    set(8, 6, 5, logZ());
    set(8, 5, 6, logZ());
    set(8, 4, 7, logZ());
    set(8, 3, 8, logZ());
    set(8, 2, 9, logZ());

    // Intermediate archer platform at Y=4
    for (let z = 3; z <= 6; z++) {
      for (let x = 3; x <= 7; x++) {
        set(x, 4, z, woodPlanks);
      }
      set(3, 5, z, woodFence);
      set(7, 5, z, woodFence);
    }
    placeBeamX(3, 7, 3, 6, logX());
    set(3, 2, 6, logY());
    set(7, 2, 6, logY());

    // High observation crow's nest at Y=7
    for (let z = 4; z <= 5; z++) {
      for (let x = 4; x <= 6; x++) {
        set(x, 7, z, woodPlanks);
      }
    }
    set(4, 8, 5, woodFence);
    set(6, 8, 5, woodFence);

    // Ladders and winch drum
    for (let y = 1; y <= 4; y++) {
      set(5, y, 6, woodFence);
    }
    for (let y = 4; y <= 7; y++) {
      set(5, y, 5, woodFence);
    }

    set(5, 2, 9, logX());
    set(4, 2, 9, woodFence);
    set(6, 2, 9, woodFence);
    set(5, 3, 9, woodTrapdoor);

    // Propped cribbing under broken wheel axle
    set(2, 0, 3, woodPlanks);
    groundSole(2, 0, 3, woodPlanks);
    set(1, 0, 3, woodPlanks);
    groundSole(1, 0, 3, woodPlanks);

  } else if (variant === 2) {
    // -------------------------------------------------------------------------
    // VARIANT 2: Smashed Trestle Ram with Direct Trojan Stone Strike
    // -------------------------------------------------------------------------
    engineName = "Battered Siege Ram of Troy";

    // West wheels intact; East front wheel smashed
    buildWheel(1, 3, false);
    buildWheel(1, 9, false);
    buildWheel(9, 3, true);
    buildWheel(9, 9, false);

    // Axles & Sills
    placeBeamX(1, 9, 1, 3, logX());
    placeBeamX(1, 9, 1, 9, logX());
    placeBeamZ(2, 1, 1, 11, logZ());
    placeBeamZ(8, 1, 1, 11, logZ());

    for (const z of [1, 3, 6, 9, 11]) {
      placeBeamX(2, 8, 1, z, logX());
      groundSole(2, 0, z, woodLog);
      groundSole(8, 0, z, woodLog);
    }

    // Floor deck
    for (let z = 2; z <= 10; z++) {
      for (let x = 3; x <= 7; x++) {
        set(x, 1, z, woodPlanks);
      }
    }

    // Intact West A-Frame Posts
    for (const z of [2, 6, 10]) {
      set(2, 2, z, logY());
      set(2, 3, z, logY());
      set(3, 3, z, woodPlanks);
      set(3, 4, z, logY());
      set(3, 5, z, logY());
      set(4, 5, z, woodPlanks);
      set(4, 6, z, logY());
      set(4, 7, z, logY());
      set(5, 7, z, woodPlanks);
    }

    // Smashed East Posts
    set(8, 2, 2, logY());
    set(8, 3, 2, woodFence);

    set(8, 2, 6, logY());
    set(8, 3, 6, logY());
    set(7, 3, 6, woodPlanks);
    set(7, 4, 6, woodFence);

    set(8, 2, 10, logY());
    set(8, 3, 10, logY());
    set(7, 3, 10, woodPlanks);
    set(7, 4, 10, logY());
    set(7, 5, 10, logY());
    set(6, 5, 10, woodPlanks);
    set(6, 6, 10, logY());
    set(6, 7, 10, logY());

    // Sagging collapsed ridge beam
    placeBeamZ(5, 8, 6, 11, strLogZ());
    set(5, 7, 5, strLogZ());
    set(6, 6, 4, strLogZ());
    set(6, 5, 3, strLogZ());
    set(7, 4, 2, strLogZ());

    // Intact West Canopy
    for (let z = 1; z <= 11; z++) {
      set(5, 9, z, slabBottom());
      set(4, 8, z, pickHide(rand()));
      set(4, 7, z, slabTop());
      set(3, 6, z, pickHide(rand()));
      set(3, 5, z, stairW());
      set(2, 4, z, pickHide(rand()));
      set(1, 4, z, slabBottom());
    }

    // Torn East Canopy (rear only; front destroyed)
    for (let z = 7; z <= 11; z++) {
      set(6, 8, z, pickHide(rand()));
      set(6, 7, z, slabTop());
      set(7, 6, z, pickHide(rand()));
      set(7, 5, z, stairE());
      set(8, 4, z, pickHide(rand()));
    }

    // Splintered timber around the breach
    set(6, 6, 6, woodFence);
    set(7, 4, 5, woodFence);
    set(8, 3, 4, woodFence);
    set(7, 2, 3, woodPlanks);

    // Trojan Boulder missile lodged inside the carriage
    const rockBlock = tStone.primary || "minecraft:stone_bricks";
    const rockAccent = tStone.accent || "minecraft:cobblestone";
    set(6, 2, 4, rockBlock);
    set(6, 3, 4, rockAccent);
    set(7, 2, 4, rockAccent);
    set(6, 2, 5, rockBlock);

    // Smashed tilted ram beam (front dropped to ground)
    set(5, 1, 0, ironHead);
    set(5, 2, 0, ironAnvil);
    set(5, 1, 1, ironHead);
    set(5, 1, 2, strLogZ());
    set(5, 2, 3, strLogZ());
    set(5, 2, 4, strLogZ());
    set(5, 3, 5, strLogZ());
    set(5, 3, 6, strLogZ());
    set(5, 4, 7, strLogZ());
    set(5, 4, 8, strLogZ());
    set(5, 4, 9, strLogZ());
    set(5, 4, 10, strLogZ());

    set(4, 4, 10, logX());
    set(6, 4, 10, logX());

    // Surviving rear suspension chains
    for (const z of [8, 10]) {
      set(5, 7, z, chainBlock);
      set(5, 6, z, chainBlock);
      set(5, 5, z, chainBlock);
    }

  } else {
    // -------------------------------------------------------------------------
    // VARIANT 3: Ox-Hide Sapping Testudo (Tortoise Bore Engine)
    // -------------------------------------------------------------------------
    engineName = "Achaean Sapping Testudo";

    // 6 Roller wheels for heavy sapping tortoise
    for (const z of [2, 6, 10]) {
      buildWheel(1, z, false);
      buildWheel(9, z, false);
      placeBeamX(1, 9, 1, z, logX());
    }

    // Side chassis sills
    placeBeamZ(2, 1, 1, 11, logZ());
    placeBeamZ(8, 1, 1, 11, logZ());

    // Cross-ribs and floor
    for (let z = 1; z <= 11; z += 2) {
      placeBeamX(2, 8, 1, z, logX());
      groundSole(2, 0, z, woodLog);
      groundSole(8, 0, z, woodLog);
    }

    for (let z = 1; z <= 11; z++) {
      for (let x = 3; x <= 7; x++) {
        set(x, 1, z, woodPlanks);
      }
    }

    // Heavy low-profile hide walls at X=1 and X=9
    for (let z = 1; z <= 11; z++) {
      set(1, 2, z, pickHide(rand()));
      set(1, 3, z, pickHide(rand()));
      set(9, 2, z, pickHide(rand()));
      set(9, 3, z, pickHide(rand()));
      set(2, 2, z, woodPlanks);
      set(8, 2, z, woodPlanks);
    }

    // Triple-sloped multi-layer hide canopy (repels Greek fire & rocks)
    for (let z = 1; z <= 11; z++) {
      set(2, 4, z, pickHide(rand()));
      set(8, 4, z, pickHide(rand()));
      set(2, 3, z, stairW());
      set(8, 3, z, stairE());

      set(3, 5, z, pickHide(rand()));
      set(7, 5, z, pickHide(rand()));
      set(3, 4, z, stairW());
      set(7, 4, z, stairE());

      set(4, 6, z, pickHide(rand()));
      set(6, 6, z, pickHide(rand()));
      set(4, 5, z, stairW());
      set(6, 5, z, stairE());

      set(5, 7, z, strLogZ());
      set(5, 8, z, slabBottom());
    }

    // Armored front shield bulkhead
    for (let x = 2; x <= 8; x++) {
      set(x, 2, 1, pickHide(rand()));
      set(x, 3, 1, pickHide(rand()));
    }
    // Bore exit portal
    set(5, 2, 1, "minecraft:air");
    set(5, 3, 1, "minecraft:air");
    set(4, 2, 1, woodLog);
    set(6, 2, 1, woodLog);
    set(5, 4, 1, stairN("top"));

    // Iron Wall Sapping Bore
    set(5, 2, 0, ironHead);
    set(5, 3, 0, ironAnvil);
    set(4, 2, 0, ironBar);
    set(6, 2, 0, ironBar);
    set(5, 1, 0, stairN("top"));

    placeBeamZ(5, 2, 2, 10, strLogZ());
    placeBeamZ(5, 3, 2, 10, logZ());

    // Sappers' dual-sided push and turn levers
    for (const z of [3, 5, 7, 9]) {
      set(4, 2, z, logX());
      set(6, 2, z, logX());
      set(4, 3, z, woodFence);
      set(6, 3, z, woodFence);
    }

    // Timber floor guide rollers
    for (const z of [2, 6, 10]) {
      set(5, 1, z, woodStripped);
    }

    // Rear sapper entry portal
    set(3, 2, 11, woodFence);
    set(7, 2, 11, woodFence);
    set(4, 2, 11, woodFence);
    set(6, 2, 11, woodFence);
  }

  return {
    name: engineName,
    seatY: 0,
    anchors: {
      front: [5, 3, 0]
    }
  };
}
